-- Reportes estándar de OpenLMIS en español (Honduras). Idempotente: se aplica en cada up/restore.
-- Plantillas compiladas con las librerías de openlmis/report:1.5.0 y openlmis/stockmanagement:5.3.0
-- (JasperReports 6.5.1) a partir de reports/es/*.jrxml. Se conservan los IDs: la UI abre
-- la lista de selección y empaque por su ID fijo.
BEGIN;
UPDATE report.jasper_templates SET name = 'Historial de alertas de cadena de frío', description = 'Alertas de monitoreo remoto de temperatura de un equipo en los últimos 30 días', data = decode('', 'hex') WHERE id = '5ccbdfe1-594f-4830-960d-801dabf36566';
UPDATE report.jasper_templates SET name = 'Errores de configuración de asignación de establecimientos', description = 'Establecimientos sin programas, roles o nodo supervisor asignados', data = decode('', 'hex') WHERE id = '7f50dac3-3768-4588-9eeb-f992f5d524fc';
UPDATE report.jasper_templates SET name = 'Resumen periódico de existencias', description = 'Existencia inicial, movimientos y existencia final por producto en un periodo', data = decode('', 'hex') WHERE id = '56704147-b795-42c3-a81a-995d8df18a19';
UPDATE report.jasper_templates SET name = 'Lista de selección y empaque', description = 'Productos, lotes y cantidades a despachar de un borrador de envío', data = decode('', 'hex') WHERE id = '583ccc35-88b7-48a8-9193-6c4857d3ff60';
UPDATE report.jasper_templates SET name = 'Existencias en mano', description = 'Existencias por establecimiento, producto y lote a una fecha', data = decode('', 'hex') WHERE id = '1fd4208c-6840-4925-a1f6-5770e8fb3e97';
UPDATE report.template_parameters SET displayname = CASE displayname WHEN 'Inventory Item ID' THEN 'ID del equipo' WHEN 'Shipment Draft ID' THEN 'ID del borrador de envío' WHEN 'Start Date' THEN 'Fecha de inicio' WHEN 'End Date' THEN 'Fecha de fin' WHEN 'Facility' THEN 'Establecimiento' WHEN 'Program' THEN 'Programa' WHEN 'Product' THEN 'Producto' WHEN 'Date' THEN 'Fecha' WHEN 'Expired Products' THEN 'Productos vencidos' WHEN 'Facility Type' THEN 'Tipo de establecimiento' WHEN 'Geographic Zone' THEN 'Zona geográfica' ELSE displayname END WHERE templateid IN ('5ccbdfe1-594f-4830-960d-801dabf36566','7f50dac3-3768-4588-9eeb-f992f5d524fc','56704147-b795-42c3-a81a-995d8df18a19','583ccc35-88b7-48a8-9193-6c4857d3ff60','1fd4208c-6840-4925-a1f6-5770e8fb3e97');
UPDATE stockmanagement.jasper_templates SET data = decode('', 'hex') WHERE name = 'Print PI';
COMMIT;
